import Cookies from 'js-cookie';
import { getAuth, type User } from 'firebase/auth';
import { z } from 'zod';

const WpErrorSchema = z.object({
  code: z.string(),
  message: z.string(),
  data: z.object({ status: z.number().optional() }).optional(),
});

const SessionResponseSchema = z.object({
  firebaseUid: z.string(),
  email: z.string(),
  wpUserId: z.number().nullable(),
  wpUserExists: z.boolean(),
});

const SignupResponseSchema = z.object({
  wpUserId: z.number(),
  email: z.string(),
  firebaseUid: z.string(),
  source: z.string(),
  appPassword: z.string().nullable().optional(),
});

const AppPasswordResponseSchema = z.object({
  wpUserId: z.number(),
  email: z.string(),
  appPassword: z.string(),
});

const DeleteAccountResponseSchema = z.object({
  message: z.string(),
  wpUserId: z.number(),
});

export type WordPressSession = z.infer<typeof SessionResponseSchema>;
export type WordPressSignupResult = z.infer<typeof SignupResponseSchema>;
export type WordPressCredentialsSync = {
  readonly wpUserId: number | null;
  readonly appPassword: string | null;
};

const WP_APP_PASSWORD_COOKIE = 'wpToken';
const WP_CREDENTIAL_OWNER_COOKIE = 'wpCredentialOwner';

const assertCurrentUser = (user: User): void => {
  if (getAuth().currentUser?.uid !== user.uid) {
    throw new AuthApiError('Your session changed. Please sign in again.', 'session_changed', 401);
  }
};

export const resetWordPressCredentialsForUser = (user: User | null): void => {
  if (user && Cookies.get(WP_CREDENTIAL_OWNER_COOKIE) === user.uid) {
    return;
  }
  Cookies.remove('userId');
  Cookies.remove(WP_APP_PASSWORD_COOKIE, { path: '/' });
  Cookies.remove(WP_CREDENTIAL_OWNER_COOKIE, { path: '/' });
};

const wpAppPasswordCookieOptions = {
  expires: 7,
  path: '/',
  secure: true,
  sameSite: 'strict' as const,
};

export type WordPressSignupSource = 'login-signup' | 'bible-study-signup' | 'google-signup';

export type WordPressSignupPayload = {
  readonly source: WordPressSignupSource;
  readonly displayName?: string;
  readonly firstName?: string;
  readonly recaptchaToken?: string;
  readonly optIn?: boolean;
};

export class AuthApiError extends Error {
  readonly code: string;
  readonly status: number;

  constructor(message: string, code: string, status: number) {
    super(message);
    this.name = 'AuthApiError';
    this.code = code;
    this.status = status;
  }
}

const getAuthApiBaseUrl = (): string => {
  const wpApiUrl = process.env.REACT_APP_WP_API_URL?.trim() ?? '';
  if (!wpApiUrl) {
    return '';
  }
  return wpApiUrl.replace('/wp/v2', '');
};

const parseWpResponse = async <T>(response: Response, schema: z.ZodType<T>): Promise<T> => {
  const json: unknown = await response.json();

  if (!response.ok) {
    const errorResult = WpErrorSchema.safeParse(json);
    if (errorResult.success) {
      throw new AuthApiError(
        errorResult.data.message,
        errorResult.data.code,
        errorResult.data.data?.status ?? response.status,
      );
    }
    throw new AuthApiError('Request failed', 'unknown_error', response.status);
  }

  const parsed = schema.safeParse(json);
  if (!parsed.success) {
    throw new AuthApiError('Invalid server response', 'invalid_response', 500);
  }

  return parsed.data;
};

export const getFirebaseIdToken = async (firebaseUser: User): Promise<string> =>
  firebaseUser.getIdToken();

const authFetch = async (
  firebaseUser: User,
  path: string,
  init?: RequestInit,
): Promise<Response> => {
  const baseUrl = getAuthApiBaseUrl();
  if (!baseUrl) {
    throw new AuthApiError('WordPress API is not configured', 'config_error', 500);
  }

  assertCurrentUser(firebaseUser);
  const idToken = await getFirebaseIdToken(firebaseUser);
  assertCurrentUser(firebaseUser);

  return fetch(`${baseUrl}${path}`, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${idToken}`,
      ...init?.headers,
    },
  });
};

export const fetchWordPressSession = async (firebaseUser: User): Promise<WordPressSession> => {
  const response = await authFetch(firebaseUser, '/revelationary/v1/auth/session', {
    method: 'POST',
  });
  const session = await parseWpResponse(response, SessionResponseSchema);
  assertCurrentUser(firebaseUser);
  if (
    session.firebaseUid !== firebaseUser.uid ||
    session.wpUserExists !== (session.wpUserId !== null)
  ) {
    throw new AuthApiError('Account association could not be verified.', 'invalid_session', 502);
  }
  return session;
};

export const createWordPressSignup = async (
  firebaseUser: User,
  payload: WordPressSignupPayload,
): Promise<WordPressSignupResult> => {
  const response = await authFetch(firebaseUser, '/revelationary/v1/auth/signup', {
    method: 'POST',
    body: JSON.stringify(payload),
  });
  return parseWpResponse(response, SignupResponseSchema);
};

export const createWordPressSignupAndStoreCredentials = async (
  firebaseUser: User,
  payload: WordPressSignupPayload,
): Promise<WordPressSignupResult> => {
  const signup = await createWordPressSignup(firebaseUser, payload);
  assertCurrentUser(firebaseUser);
  persistWordPressUserId(signup.wpUserId, firebaseUser);
  if (!storeAppPasswordIfPresent(signup.appPassword, firebaseUser)) {
    await provisionWordPressAppPassword(firebaseUser);
  }
  return signup;
};

export const persistWordPressUserId = (wpUserId: number, firebaseUser: User): void => {
  assertCurrentUser(firebaseUser);
  Cookies.set('userId', wpUserId.toString());
};

export const getStoredWordPressAppPassword = (): string | undefined => {
  const uid = getAuth().currentUser?.uid;
  return uid && Cookies.get(WP_CREDENTIAL_OWNER_COOKIE) === uid
    ? Cookies.get(WP_APP_PASSWORD_COOKIE)
    : undefined;
};

export const persistWordPressAppPassword = (appPassword: string, firebaseUser: User): void => {
  assertCurrentUser(firebaseUser);
  Cookies.set(WP_APP_PASSWORD_COOKIE, appPassword, wpAppPasswordCookieOptions);
  Cookies.set(WP_CREDENTIAL_OWNER_COOKIE, firebaseUser.uid, wpAppPasswordCookieOptions);
};

const storeAppPasswordIfPresent = (
  appPassword: string | null | undefined,
  firebaseUser: User,
): string | null => {
  if (!appPassword) {
    return null;
  }
  persistWordPressAppPassword(appPassword, firebaseUser);
  return appPassword;
};

const pendingPasswords = new Map<string, Promise<string>>();
export const provisionWordPressAppPassword = async (firebaseUser: User): Promise<string> => {
  assertCurrentUser(firebaseUser);
  const pending = pendingPasswords.get(firebaseUser.uid);
  if (pending) {
    return pending;
  }
  const request = (async () => {
    const response = await authFetch(firebaseUser, '/revelationary/v1/auth/app-password', {
      method: 'POST',
    });
    const data = await parseWpResponse(response, AppPasswordResponseSchema);
    assertCurrentUser(firebaseUser);
    persistWordPressUserId(data.wpUserId, firebaseUser);
    persistWordPressAppPassword(data.appPassword, firebaseUser);
    return data.appPassword;
  })();
  pendingPasswords.set(firebaseUser.uid, request);
  try {
    return await request;
  } finally {
    pendingPasswords.delete(firebaseUser.uid);
  }
};

/**
 * Sync WP user id and Comment API password after Firebase auth.
 * Reuses cookie when present; otherwise provisions a new app password server-side.
 */
export const syncWordPressCredentials = async (
  firebaseUser: User,
): Promise<WordPressCredentialsSync> => {
  const session = await fetchWordPressSession(firebaseUser);

  if (session.wpUserId !== null) {
    persistWordPressUserId(session.wpUserId, firebaseUser);
  }

  if (!session.wpUserExists || session.wpUserId === null) {
    return { wpUserId: null, appPassword: null };
  }
  const existingPassword = getStoredWordPressAppPassword();
  if (existingPassword) {
    return { wpUserId: session.wpUserId, appPassword: existingPassword };
  }

  const appPassword = await provisionWordPressAppPassword(firebaseUser);
  return {
    wpUserId: session.wpUserId,
    appPassword,
  };
};

export const syncWordPressUserId = async (firebaseUser: User): Promise<number | null> => {
  const session = await fetchWordPressSession(firebaseUser);
  if (session.wpUserId !== null) {
    persistWordPressUserId(session.wpUserId, firebaseUser);
  }
  return session.wpUserId;
};

/**
 * Resolve WordPress user for a Firebase session; create subscriber if missing.
 */
export const deleteWordPressAccount = async (firebaseUser: User): Promise<void> => {
  const response = await authFetch(firebaseUser, '/revelationary/v1/auth/account', {
    method: 'DELETE',
  });
  await parseWpResponse(response, DeleteAccountResponseSchema);
};

export const ensureWordPressUser = async (
  firebaseUser: User,
  signupPayload?: WordPressSignupPayload,
): Promise<number> => {
  const session = await fetchWordPressSession(firebaseUser);

  if (session.wpUserId !== null) {
    persistWordPressUserId(session.wpUserId, firebaseUser);
    if (!getStoredWordPressAppPassword()) {
      await provisionWordPressAppPassword(firebaseUser);
    }
    return session.wpUserId;
  }

  if (!signupPayload) {
    throw new AuthApiError('No WordPress account exists for this user', 'wp_user_missing', 404);
  }

  let signup: WordPressSignupResult;
  try {
    signup = await createWordPressSignup(firebaseUser, signupPayload);
  } catch (error) {
    // Another tab/request may have completed provisioning after our session read.
    // Resolve through the authenticated session; never retry account creation blindly.
    if (error instanceof AuthApiError && error.code === 'user_exists') {
      return ensureWordPressUser(firebaseUser);
    }
    throw error;
  }
  assertCurrentUser(firebaseUser);
  persistWordPressUserId(signup.wpUserId, firebaseUser);
  if (!storeAppPasswordIfPresent(signup.appPassword, firebaseUser)) {
    await provisionWordPressAppPassword(firebaseUser);
  }
  return signup.wpUserId;
};
