import { z } from 'zod';

import { stripFbvCommentary } from '../utils/bibleTextUtils';
import { parseSourceVerseLabel, sourceVerseLabelValue } from '../utils/sourceVerseLabels';

import { BIBLE_EDITIONS, BibleEdition, bibleAssetUrls } from '../data/bibleEditions';
export const translationToBibleFolder: Readonly<Record<string, string>> = Object.fromEntries(
  BIBLE_EDITIONS.map((edition) => [edition.id, edition.folder]),
);

const KJVAPP_SEARCH_URL: Readonly<Partial<Record<string, string>>> = {
  kjv: 'https://kjvapp.com/api/search?text=',
  cuv: 'https://cuv.kjvapp.com/api/search?text=',
  lut: 'https://lut.kjvapp.com/api/search?text=',
};

const SearchIndexEntrySchema = z.object({
  b: z.string(),
  c: z.number().int().positive(),
  v: z.number().int().nonnegative().or(z.string()),
  t: z.string(),
});

const SearchIndexEntryLenientSchema = z.object({
  b: z.string(),
  c: z.number().or(z.string()),
  v: z.number().or(z.string()),
  t: z.string(),
});

const SearchIndexSchema = z.array(SearchIndexEntrySchema);

const VerseSearchResultSchema = z.object({
  id: z.number().or(z.string()),
  book: z.string(),
  chapter: z.number().or(z.string()),
  verse: z.number().or(z.string()),
  text: z.string(),
});

const KjvAppSearchResultsSchema = z.array(VerseSearchResultSchema);

export type VerseSearchResult = z.infer<typeof VerseSearchResultSchema> & {
  translation: BibleEdition['id'];
};

export class SearchInputError extends Error {
  constructor() {
    super('Use double quotes around a keyword or phrase.');
    this.name = 'SearchInputError';
  }
}

export class BibleSearchUnavailableError extends Error {
  constructor() {
    super('Bible search is unavailable. Please try again.');
    this.name = 'BibleSearchUnavailableError';
  }
}

/** Normalise phrase-search hits for Dashboard `Verse` state. */
export function toDashboardVerse(result: VerseSearchResult): {
  book: string;
  chapter: number;
  verse: string | number;
  text: string;
  id: string;
  translation: BibleEdition['id'];
} {
  return {
    id: String(result.id),
    book: result.book,
    chapter: Number(result.chapter),
    verse: sourceVerseLabelValue(result.verse),
    text: result.text,
    translation: result.translation,
  };
}

const indexCache = new Map<string, VerseSearchResult[] | null>();
const indexLoadPromises = new Map<string, Promise<VerseSearchResult[] | null>>();

/** Warm the search index in the background (call on app load / translation change). */
export function prefetchBibleSearchIndex(translation: string): void {
  const edition = BIBLE_EDITIONS.find((item) => item.id === translation);
  if (!edition) {
    return;
  }
  const bibleFolder = edition.folder;
  if (!indexCache.has(bibleFolder) && !indexLoadPromises.has(bibleFolder)) {
    void fetchSearchIndex(bibleFolder);
  }
}

/** Extract phrase inside double quotes, e.g. `"light"` → `light`. */
export function parseQuotedPhrase(term: string): string | null {
  const match = term.trim().match(/^"([^"]+)"$/);
  const phrase = match?.[1]?.trim();
  return phrase && phrase.length > 0 ? phrase : null;
}

export function isQuotedPhraseSearch(term: string): boolean {
  return parseQuotedPhrase(term) !== null;
}

function indexUrls(bibleFolder: string): string[] {
  const edition = BIBLE_EDITIONS.find((item) => item.folder === bibleFolder);
  return [
    `/search/${bibleFolder}.json`,
    ...(edition ? bibleAssetUrls(edition.id, 'search-index.json') : []),
  ];
}

function parseSearchIndexEntries(
  json: unknown,
  translation: BibleEdition['id'],
): VerseSearchResult[] | null {
  if (!Array.isArray(json)) {
    return null;
  }

  const verses: VerseSearchResult[] = [];
  for (const item of json) {
    const parsed = SearchIndexEntryLenientSchema.safeParse(item);
    if (!parsed.success) {
      return null;
    }
    const chapter = Number(parsed.data.c);
    if (
      !String(parsed.data.v).trim() ||
      !Number.isFinite(chapter) ||
      !parseSourceVerseLabel(parsed.data.v) ||
      chapter < 1
    ) {
      return null;
    }
    const strict = SearchIndexEntrySchema.safeParse({
      b: parsed.data.b,
      c: chapter,
      v: sourceVerseLabelValue(parsed.data.v),
      t: parsed.data.t,
    });
    if (strict.success) {
      verses.push(entryToVerse(strict.data, verses.length + 1, translation));
    } else {
      return null;
    }
  }

  return verses.length > 0 ? verses : null;
}

function normalizeBookName(book: string): string {
  return book.trimEnd();
}

function entryToVerse(
  entry: z.infer<typeof SearchIndexEntrySchema>,
  id: number,
  translation: BibleEdition['id'],
): VerseSearchResult {
  return {
    id,
    book: normalizeBookName(entry.b),
    chapter: entry.c,
    verse: entry.v,
    text: entry.t,
    translation,
  };
}

async function fetchSearchIndex(bibleFolder: string): Promise<VerseSearchResult[] | null> {
  if (indexCache.has(bibleFolder)) {
    return indexCache.get(bibleFolder) ?? null;
  }

  const pending = indexLoadPromises.get(bibleFolder);
  if (pending) {
    return pending;
  }

  const loadPromise = (async (): Promise<VerseSearchResult[] | null> => {
    const edition = BIBLE_EDITIONS.find((item) => item.folder === bibleFolder);
    if (!edition) {
      return null;
    }
    for (const url of indexUrls(bibleFolder)) {
      try {
        const json = await fetchSearchJson(url);
        const verses = parseSearchIndexEntries(json, edition.id);
        if (verses) {
          indexCache.set(bibleFolder, verses);
          return verses;
        }
      } catch {
        // try next URL
      }
    }

    return null;
  })();

  indexLoadPromises.set(bibleFolder, loadPromise);
  try {
    return await loadPromise;
  } finally {
    indexLoadPromises.delete(bibleFolder);
  }
}

function searchIndex(verses: VerseSearchResult[], phrase: string): VerseSearchResult[] {
  const needle = phrase.normalize('NFC').toLowerCase();
  return verses.filter((verse) => verse.text.normalize('NFC').toLowerCase().includes(needle));
}

async function searchViaKjvApp(
  term: string,
  translation: BibleEdition['id'],
  signal?: AbortSignal,
): Promise<VerseSearchResult[] | null> {
  const baseUrl = KJVAPP_SEARCH_URL[translation];
  if (!baseUrl) {
    return null;
  }

  try {
    const json = await fetchSearchJson(`${baseUrl}${encodeURIComponent(term.trim())}`, signal);
    const parsed = KjvAppSearchResultsSchema.safeParse(json);
    if (
      !parsed.success ||
      parsed.data.some(
        (verse) =>
          !SearchIndexEntrySchema.safeParse({
            b: verse.book,
            c: Number(verse.chapter),
            v: verse.verse,
            t: verse.text,
          }).success || !String(verse.verse).trim(),
      )
    ) {
      return null;
    }
    return parsed.data.map((verse, index) => ({
      ...verse,
      id: verse.id ?? index + 1,
      book: normalizeBookName(String(verse.book)),
      translation,
    }));
  } catch {
    return null;
  }
}

// Cancel one search without cancelling an index download shared by other consumers.
function withSignal<T>(pending: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (!signal) {
    return pending;
  }
  return new Promise((resolve, reject) => {
    const abort = () => reject(new DOMException('Search cancelled', 'AbortError'));
    const cleanup = () => signal.removeEventListener('abort', abort);
    pending.then(
      (value) => {
        cleanup();
        resolve(value);
      },
      (error) => {
        cleanup();
        reject(error);
      },
    );
    if (signal.aborted) {
      abort();
    } else {
      signal.addEventListener('abort', abort, { once: true });
    }
  });
}

async function fetchSearchJson(url: string, signal?: AbortSignal): Promise<unknown> {
  const controller = new AbortController();
  const abort = () => controller.abort();
  if (signal?.aborted) {
    abort();
  }
  signal?.addEventListener('abort', abort, { once: true });
  const timeout = setTimeout(abort, 8000);
  try {
    return await withSignal(
      (async () => {
        const response = await fetch(url, { signal: controller.signal });
        if (!response.ok) {
          throw new BibleSearchUnavailableError();
        }
        return response.json();
      })(),
      controller.signal,
    );
  } finally {
    clearTimeout(timeout);
    signal?.removeEventListener('abort', abort);
  }
}

/**
 * Search the active Bible translation for a quoted word or phrase.
 * Uses CDN search-index.json when available, otherwise falls back to kjvapp.com (kjv/cuv/lut).
 */
export async function searchBiblePhrase(
  term: string,
  translation: string,
  signal?: AbortSignal,
): Promise<VerseSearchResult[]> {
  const phrase = parseQuotedPhrase(term);
  if (!phrase) {
    throw new SearchInputError();
  }
  if (signal?.aborted) {
    throw new DOMException('Search cancelled', 'AbortError');
  }
  const edition = BIBLE_EDITIONS.find((item) => item.id === translation);
  if (!edition) {
    throw new BibleSearchUnavailableError();
  }
  const index = await withSignal(fetchSearchIndex(edition.folder), signal);
  if (index) {
    return searchIndex(index, phrase);
  }

  const kjvAppResults = await searchViaKjvApp(term, edition.id, signal);
  if (signal?.aborted) {
    throw new DOMException('Search cancelled', 'AbortError');
  }
  if (kjvAppResults !== null) {
    return kjvAppResults;
  }
  throw new BibleSearchUnavailableError();
}

export function clearSearchIndexCache(): void {
  indexCache.clear();
}

/** Used by the index generator script. */
export function compactVerseForIndex(
  book: string,
  chapter: number | string,
  verse: number | string,
  text: string,
  translation: string,
): z.infer<typeof SearchIndexEntrySchema> {
  const chapterStr = String(chapter);
  const verseStr = String(verse);
  const cleanedText =
    translation === 'fbv' ? stripFbvCommentary(text, chapterStr, verseStr) : text.trim();

  return {
    b: normalizeBookName(book),
    c: Number(chapter),
    v: sourceVerseLabelValue(verse),
    t: cleanedText,
  };
}

export { SearchIndexEntrySchema, SearchIndexSchema };
